const envelope = $input.first().json;
const body = envelope.body ?? envelope;
const content = String(body.content ?? '').trim().slice(0, 1900);
if (!content) throw new Error('feedback senza contenuto');

const topic = (content.match(/^\[([^\]]+)\]/m)?.[1] ?? 'other').toLowerCase();
const urgent = /(crash|blocc|freeze|non si avvia|salvataggio|perd|invisibil|trasparen)/i.test(content);
const important = urgent || /\[(bug|performance)\]/i.test(content);
const priority = urgent ? 'URGENTE' : important ? 'ALTA' : topic === 'balance' ? 'MEDIA' : 'NORMALE';
const now = new Date();
const day = now.toISOString().slice(0, 10).replace(/-/g, '');
let hash = 2166136261;
for (const char of content) { hash ^= char.charCodeAt(0); hash = Math.imul(hash, 16777619); }
const ticket = `FB-${day}-${(hash >>> 0).toString(16).slice(0, 6).toUpperCase()}`;

let diagnostics = {};
const rawDiagnostics = content.match(/--- contesto tecnico ---\s*([\s\S]+)$/);
if (rawDiagnostics) { try { diagnostics = JSON.parse(rawDiagnostics[1]); } catch {} }
const colour = priority === 'URGENTE' ? 15158332 : priority === 'ALTA' ? 15105570 : priority === 'MEDIA' ? 3447003 : 5763719;
const cleanMessage = content.replace(/--- contesto tecnico ---[\s\S]*$/, '').trim();
const fields = [
  { name: 'Categoria', value: topic.toUpperCase(), inline: true },
  { name: 'Priorità', value: priority, inline: true },
  { name: 'Stato', value: 'NUOVO', inline: true },
];
if (diagnostics.version) fields.push({ name: 'Versione', value: String(diagnostics.version).slice(0, 100), inline: true });
if (diagnostics.balance) fields.push({ name: 'Bilanciamento', value: String(diagnostics.balance).slice(0, 100), inline: true });

return [{ json: {
  ticket, topic, priority, receivedAt: now.toISOString(), diagnostics,
  discordPayload: {
    embeds: [{ title: `${ticket} · ${priority}`, description: cleanMessage.slice(0, 3900), color: colour, fields, footer: { text: 'Steam Circuit Padel Pro · feedback in triage' }, timestamp: now.toISOString() }],
    allowed_mentions: { parse: [] }
  }
} }];
